/* Fit the complete object field without a separate tool tray. Very short
   windows may scroll; handles retain a 48px physical touch area. */
.game { width: min(100%, calc((100svh - 350px) * .654545)); min-width: min(260px, 100%); margin-inline: auto; }
@media (max-height: 740px) {
  .shell { padding-top: 12px; }
  .page-header { margin-bottom: 14px; }
  .intro > p:last-child { margin-bottom: 12px; }
  .eyebrow { margin-bottom: 5px; }
  h1 { font-size: 23px; margin-bottom: 8px; }
  .game { width: min(100%, calc((100svh - 285px) * .654545)); }
  .scene-picker { margin-bottom: 8px; gap: 4px; }
}
@media (max-width: 360px) { .shell { padding-inline: 12px; } }
@media (min-width: 800px) { .shell { padding-top: 32px; } }

