(() => {
  'use strict';
  const core = globalThis.PuffPuzzle;
  const byId = id => document.getElementById(id);
  const stage = byId('stage'), pieceRoot = byId('pieces'), finish = byId('finish');
  let state = core.fresh(), capture = null, previousAnnouncement = '';
  const elements = new Map();
  const toPoint = event => {
    const rect = stage.getBoundingClientRect();
    return { x: (event.clientX - rect.left) / rect.width * core.WIDTH, y: (event.clientY - rect.top) / rect.height * core.HEIGHT };
  };
  function announce(message) {
    if (message !== previousAnnouncement) {
      byId('status').textContent = message;
      previousAnnouncement = message;
    }
  }
  function releaseCapture() {
    const previous = capture;
    capture = null;
    if (previous && previous.element.hasPointerCapture(previous.pointerId)) {
      try { previous.element.releasePointerCapture(previous.pointerId); }
      catch (error) { if (error.name !== 'NotFoundError') throw error; }
    }
  }
  function cancelInteraction() {
    if (!state.drag && !state.selected && !capture) return;
    state = core.putDown(state);
    releaseCapture();
    render();
  }
  function focusNext() {
    const next = state.pieces.find(piece => piece.progress < 1);
    if (next) elements.get(next.id).handle.focus({ preventScroll: true });
  }
  function buildPieces() {
    const scene = core.getScene(state.sceneId);
    pieceRoot.replaceChildren();
    elements.clear();
    for (const piece of scene.items) {
      const element = document.createElement('article');
      element.className = `balloon${piece.width < 220 ? ' balloon-small' : ''}${scene.kind === 'coupon' ? ' coupon' : ''}`;
      const sign = Math.sign(piece.vector.x);
      element.style.cssText = `left:${piece.x / core.WIDTH * 100}%;top:${piece.y / core.HEIGHT * 100}%;width:${piece.width / core.WIDTH * 100}%;height:${piece.height / core.HEIGHT * 100}%;--balloon:${piece.color};--tail-sign:${sign};--valve-origin:${(piece.target.x - sign * 24 - piece.x) / piece.width * 100}%;`;
      // The loop + loose tail, or folded paper underside, exist before input.
      element.innerHTML = `<div class="balloon-body"><div class="balloon-topline"><span>${piece.label}</span><span class="badge">${piece.badge}</span></div><h2>${piece.title}</h2><p>${piece.copy}</p></div><span class="knot" aria-hidden="true"></span><span class="air-lines" aria-hidden="true">﹏<br>﹏</span><button class="handle" type="button"><span class="handle-material" aria-hidden="true"></span></button>`;
      const handle = element.querySelector('.handle'), knot = element.querySelector('.knot');
      knot.style.left = `${(piece.target.x - sign * 24 - piece.x) / piece.width * 100}%`;
      knot.style.top = `${(piece.target.y - piece.y) / piece.height * 100}%`;
      const isCurrent = () => state.sceneId === scene.id && elements.get(piece.id)?.element === element;
      handle.addEventListener('focus', () => {
        if (!isCurrent() || state.drag) return;
        state = core.select(state, piece.id);
        render();
      });
      handle.addEventListener('click', event => {
        if (!isCurrent() || event.detail > 0) return;
        state = core.select(state, piece.id);
        render();
      });
      handle.addEventListener('pointerdown', event => {
        if (!isCurrent() || !event.isPrimary || event.button !== 0 || capture) return;
        event.preventDefault();
        state = core.begin(state, piece.id, toPoint(event), event.pointerId);
        if (!state.drag) return;
        capture = { element: handle, pointerId: event.pointerId };
        try { handle.setPointerCapture(event.pointerId); }
        catch (error) {
          if (error.name !== 'NotFoundError' && error.name !== 'InvalidStateError') throw error;
          cancelInteraction();
          return;
        }
        handle.focus({ preventScroll: true });
        render();
      });
      const ownsPointer = event => isCurrent() && capture?.element === handle && capture.pointerId === event.pointerId;
      handle.addEventListener('pointermove', event => {
        if (!ownsPointer(event)) return;
        if (event.buttons === 0 || event.clientX < 0 || event.clientY < 0 || event.clientX >= window.innerWidth || event.clientY >= window.innerHeight) {
          cancelInteraction();
          return;
        }
        state = core.move(state, toPoint(event), event.pointerId);
        const cleared = !state.drag;
        if (cleared) releaseCapture();
        render();
        if (cleared && !state.completed) focusNext();
      });
      const endPointer = event => {
        if (!ownsPointer(event)) return;
        const point = toPoint(event);
        const tapped = event.type === 'pointerup' && state.drag && Math.hypot(point.x - state.drag.point.x, point.y - state.drag.point.y) < 4;
        if (event.type === 'pointerup') state = core.move(state, point, event.pointerId);
        const cleared = !state.drag;
        state = core.end(state, event.pointerId);
        // A tap selects for optional directional controls, but never solves.
        if (tapped) state = core.select(state, piece.id);
        releaseCapture();
        render();
        if (cleared && !state.completed) focusNext();
      };
      handle.addEventListener('pointerup', endPointer);
      handle.addEventListener('pointercancel', endPointer);
      handle.addEventListener('lostpointercapture', event => {
        if (!ownsPointer(event) || handle.hasPointerCapture(event.pointerId)) return;
        cancelInteraction();
      });
      element.querySelector('.balloon-body').addEventListener('pointerdown', () => {
        if (!isCurrent()) return;
        state = core.probe(state, piece.id);
        element.classList.remove('probe');
        void element.offsetWidth;
        render();
      });
      pieceRoot.append(element);
      elements.set(piece.id, { element, handle, body: element.querySelector('.balloon-body') });
    }
  }
  function render() {
    const scene = core.getScene(state.sceneId), completedBefore = !finish.hidden;
    for (const piece of state.pieces) {
      const node = elements.get(piece.id), item = scene.items.find(item => item.id === piece.id);
      const cleared = piece.progress === 1, feedback = state.feedback?.id === piece.id ? state.feedback : null;
      const point = core.position(state, piece.id);
      node.element.classList.toggle('cleared', cleared);
      node.element.classList.toggle('probe', feedback?.kind === 'probe');
      node.element.classList.toggle('strained', feedback?.kind === 'strain');
      node.element.style.setProperty('--air', 1 - piece.progress);
      node.element.style.setProperty('--removed', piece.progress);
      node.element.setAttribute('aria-hidden', String(cleared));
      node.handle.disabled = cleared;
      node.handle.style.left = `${(point.x - item.x + (feedback?.x || 0)) / item.width * 100}%`;
      node.handle.style.top = `${(point.y - item.y + (feedback?.y || 0)) / item.height * 100}%`;
      node.handle.classList.toggle('selected', state.selected === piece.id);
      node.handle.classList.toggle('dragging', state.drag?.id === piece.id);
      node.handle.setAttribute('aria-pressed', String(state.selected === piece.id));
      node.handle.setAttribute('aria-label', `${item.label}, ${scene.targetName}. ${scene.progressName} ${Math.round(piece.progress * 100)}%. 방향키로 움직일 수 있습니다.`);
      if (scene.kind === 'coupon') node.body.style.clipPath = core.paperClip(piece.progress);
    }
    const count = state.pieces.filter(piece => piece.progress === 1).length;
    byId('counter').textContent = `정리 ${count} / ${state.pieces.length}`;
    for (const key of Object.keys(core.DIRECTIONS)) byId(key).disabled = !state.selected || Boolean(state.drag) || state.completed;
    finish.hidden = !state.completed;
    const message = state.event === 'cleared' ? `후우! ${count}개가 사라졌어요.` : scene.messages[state.event];
    announce(state.completed ? scene.completeMessage : message);
    byId('feedback-icon').textContent = state.completed ? '✓' : state.event === 'strain' ? '⌁' : '·';
    if (state.completed && !completedBefore) byId('finish-title').focus({ preventScroll: true });
  }
  function nudge(key) {
    const before = state.selected;
    state = core.nudge(state, key);
    render();
    if (before && !state.selected && !state.completed) focusNext();
  }
  for (const key of Object.keys(core.DIRECTIONS)) byId(key).addEventListener('click', () => nudge(key));
  document.addEventListener('keydown', event => {
    if (event.key === 'Escape') cancelInteraction();
    else if (state.selected && (stage.closest('.game').contains(document.activeElement) || byId('direction-controls').contains(document.activeElement)) && Object.hasOwn(core.DIRECTIONS, event.key)) {
      event.preventDefault();
      nudge(event.key);
    }
  });
  window.addEventListener('blur', cancelInteraction);
  window.addEventListener('pagehide', cancelInteraction);
  document.addEventListener('visibilitychange', () => { if (document.hidden) cancelInteraction(); });
  document.addEventListener('pointerout', event => { if (event.relatedTarget === null && event.pointerId === capture?.pointerId) cancelInteraction(); });
  function startScene(sceneId, focusObject = true) {
    state = core.fresh(sceneId);
    releaseCapture();
    const scene = core.getScene(state.sceneId);
    stage.setAttribute('data-scene', scene.id);
    byId('game').setAttribute('aria-label', `${scene.label} 퍼즐`);
    byId('edition').textContent = `작은 화면 정리 · ${scene.number}`;
    byId('scene-eyebrow').textContent = scene.eyebrow;
    byId('finish-copy').textContent = scene.finishCopy;
    byId('restart').textContent = scene.restartLabel;
    byId('scene-restart').setAttribute('aria-label', `${scene.label} 처음부터 다시 시작`);
    for (const option of Object.values(core.SCENES)) byId(`scene-${option.id}`).setAttribute('aria-pressed', String(option.id === scene.id));
    buildPieces();
    render();
    if (focusObject) focusNext();
  }
  byId('restart').addEventListener('click', () => startScene(state.sceneId));
  byId('scene-restart').addEventListener('click', () => startScene(state.sceneId));
  for (const scene of Object.values(core.SCENES)) byId(`scene-${scene.id}`).addEventListener('click', () => startScene(scene.id));
  startScene(core.DEFAULT_SCENE, false);
})();

