// DOM-free direct manipulation. Each object's visible loose end defines its motion.
(() => {
  'use strict';
  const WIDTH = 360, HEIGHT = 550;
  const SCENES = globalThis.PuffScenes, DEFAULT_SCENE = 'balloons';
  const getScene = id => Object.hasOwn(SCENES, id) ? SCENES[id] : SCENES[DEFAULT_SCENE];
  const clamp = value => Math.max(0, Math.min(1, value));
  const validPoint = point => point && Number.isFinite(point.x) && Number.isFinite(point.y);
  const active = (state, id) => state.pieces.find(piece => piece.id === id && piece.progress < 1);
  const config = (state, id) => getScene(state.sceneId).items.find(piece => piece.id === id);
  const fresh = (sceneId = DEFAULT_SCENE) => ({ sceneId: getScene(sceneId).id, pieces: getScene(sceneId).items.map(({ id }) => ({ id, progress: 0 })), drag: null, selected: null, feedback: null, event: 'ready', completed: false });
  function position(state, id) {
    const piece = config(state, id), progress = state.pieces.find(item => item.id === id).progress;
    return { x: piece.target.x + piece.vector.x * progress, y: piece.target.y + piece.vector.y * progress };
  }
  function select(state, id) {
    if (state.completed || state.drag || !active(state, id)) return state;
    return { ...state, selected: id, feedback: null, event: 'grabbed' };
  }
  function begin(state, id, point, pointerId = 1) {
    const piece = active(state, id);
    if (state.completed || state.drag || !piece || !validPoint(point)) return state;
    return { ...state, selected: id, feedback: null, event: 'grabbed', drag: { pointerId, id, point: { ...point }, startProgress: piece.progress } };
  }
  function updateProgress(state, id, progress) {
    const normalized = progress >= 1 - 1e-9 ? 1 : clamp(progress);
    const pieces = state.pieces.map(piece => piece.id === id ? { ...piece, progress: normalized } : piece);
    const cleared = normalized === 1;
    return { ...state, pieces, feedback: null, drag: cleared ? null : state.drag, selected: cleared ? null : id, event: cleared ? 'cleared' : 'progress', completed: pieces.every(piece => piece.progress === 1) };
  }
  function applyMotion(state, id, delta, base) {
    const piece = active(state, id), vector = config(state, id).vector;
    const projected = (delta.x * vector.x + delta.y * vector.y) / (vector.x ** 2 + vector.y ** 2);
    const next = clamp(base + projected);
    if (next > piece.progress) return updateProgress(state, id, next);
    if (projected > 0 && Math.abs(next - piece.progress) < 1e-9) return { ...state, event: 'progress', feedback: null };
    if (Math.hypot(delta.x, delta.y) < 3) return state;
    const length = Math.hypot(delta.x, delta.y);
    return { ...state, event: 'strain', feedback: { id, kind: 'strain', x: delta.x / length * 6, y: delta.y / length * 6 } };
  }
  function move(state, point, pointerId = 1) {
    const drag = state.drag;
    if (!drag || pointerId !== drag.pointerId || !validPoint(point)) return state;
    return applyMotion(state, drag.id, { x: point.x - drag.point.x, y: point.y - drag.point.y }, drag.startProgress);
  }
  function end(state, pointerId = 1) {
    if (!state.drag || state.drag.pointerId !== pointerId) return state;
    return putDown(state);
  }
  function putDown(state) {
    if (state.completed) return state;
    return { ...state, drag: null, selected: null, feedback: null, event: 'paused' };
  }
  const DIRECTIONS = Object.freeze({ ArrowLeft: { x: -1, y: 0 }, ArrowRight: { x: 1, y: 0 }, ArrowUp: { x: 0, y: -1 }, ArrowDown: { x: 0, y: 1 } });
  function nudge(state, key) {
    const piece = active(state, state.selected), direction = Object.hasOwn(DIRECTIONS, key) ? DIRECTIONS[key] : null;
    if (!piece || state.drag || !direction) return state;
    const vector = config(state, piece.id).vector;
    const distance = Math.hypot(vector.x, vector.y) * .35;
    return applyMotion(state, piece.id, { x: direction.x * distance, y: direction.y * distance }, piece.progress);
  }
  function probe(state, id) {
    if (!active(state, id) || state.drag) return state;
    return { ...state, event: 'probe', feedback: { id, kind: 'probe', x: 0, y: 0 } };
  }
  // Remainder of a sheet peeled diagonally from its top-right corner. The small
  // initial cut is a visible clue, not earned progress. Percent-space polygon.
  function paperClip(progress) {
    const cut = .16 + clamp(progress) * 1.84;
    if (cut <= 1) return `polygon(0 0, ${(1 - cut) * 100}% 0, 100% ${cut * 100}%, 100% 100%, 0 100%)`;
    return `polygon(0 ${(cut - 1) * 100}%, ${(2 - cut) * 100}% 100%, 0 100%)`;
  }
  globalThis.PuffPuzzle = Object.freeze({ WIDTH, HEIGHT, SCENES, DEFAULT_SCENE, DIRECTIONS, getScene, fresh, position, begin, move, end, select, nudge, putDown, probe, paperClip });
})();

