// Local content and visible object geometry. No prescribed order between ads.
(() => {
  'use strict';
  const freeze = value => {
    if (value && typeof value === 'object') {
      Object.values(value).forEach(freeze);
      Object.freeze(value);
    }
    return value;
  };
  globalThis.PuffScenes = freeze({
    balloons: {
      id: 'balloons', number: '01', label: '알림 풍선', kind: 'balloon',
      eyebrow: '잔뜩 부풀린 말들.', targetName: '느슨한 매듭 꼬리',
      progressName: '풀린 매듭', restartLabel: '다시 부풀리기 ↺', finishCopy: '세 개의 알림에서 공기를 뺐어요.',
      completeMessage: '세 개의 알림을 모두 정리했어요. 다시 부풀리기로 재시작할 수 있어요.',
      messages: { ready: '무엇이 공기를 붙잡고 있을까요?', grabbed: '매듭 끝이 잡혔어요.', progress: '매듭이 풀리며 공기가 새어 나와요.', paused: '매듭이 느슨해진 채로 남았어요.', strain: '그쪽으로는 매듭이 팽팽해져요.', probe: '몸통은 다시 부풀어요. 목의 매듭이 흔들리네요.' },
      items: [
        { id: 'flash', x: 36, y: 28, width: 282, height: 146, target: { x: 229, y: 184 }, vector: { x: 44, y: 0 }, color: '#f3a28f', label: '반짝 특가', badge: '99+', title: '지금! 지금! 지금!', copy: '놓치면 아쉬울 것 같은 기분만 드려요.' },
        { id: 'bonus', x: 12, y: 202, width: 238, height: 138, target: { x: 74, y: 350 }, vector: { x: -44, y: 0 }, color: '#eed887', label: '선물 도착', badge: '+999', title: '선물이 산더미!', copy: '열어도 열어도 알림이 또 와요.' },
        { id: 'vip', x: 136, y: 352, width: 206, height: 126, target: { x: 282, y: 488 }, vector: { x: 44, y: 0 }, color: '#c6b9df', label: '특별한 당신께', badge: 'VIP', title: '딱, 당신만요!', copy: '모두에게 똑같이 보낸 비밀 알림.' },
      ],
    },
    coupons: {
      id: 'coupons', number: '02', label: '쿠폰 폭탄', kind: 'coupon',
      eyebrow: '떼어도 또 오는 혜택.', targetName: '들린 종이 모서리',
      progressName: '벗겨진 종이', restartLabel: '쿠폰 다시 펼치기 ↺', finishCopy: '두 장의 과장된 쿠폰 안내를 벗겼어요.',
      completeMessage: '쿠폰 안내 두 장을 모두 치웠어요. 쿠폰 다시 펼치기로 재시작할 수 있어요.',
      messages: { ready: '종이 밑으로 조용한 풍경이 보여요.', grabbed: '들린 모서리가 잡혔어요.', progress: '종이가 접히며 뒤의 풍경이 드러나요.', paused: '벗긴 모서리가 그 자리에 남았어요.', strain: '붙어 있는 쪽으로 종이가 팽팽해져요.', probe: '종이는 붙어 있지만 한쪽 모서리가 들썩여요.' },
      items: [
        { id: 'coupon-million', x: 18, y: 36, width: 324, height: 196, target: { x: 316, y: 62 }, vector: { x: -272, y: 144 }, color: '#ffe29a', label: '쿠폰이 쏟아집니다', badge: '100장', title: '999,999원', copy: '할인보다 안내가 더 큽니다.\n누구에게나 드리는 특별한 알림!' },
        { id: 'coupon-again', x: 32, y: 278, width: 306, height: 214, target: { x: 312, y: 304 }, vector: { x: -254, y: 162 }, color: '#ffc2ae', label: '앗! 쿠폰이 또 왔어요', badge: '한 장 더', title: '할인 위에 할인!', copy: '겹겹이 쌓인 혜택 안내.\n화면까지 꽉 채워 드려요.' },
      ],
