  });
})();

styles.css.text:
:root { font-family: "Malgun Gothic", "Apple SD Gothic Neo", system-ui, sans-serif; color: #20353d; background: #f3f1e9; font-synthesis: none; }
* { box-sizing: border-box; }
body { margin: 0; }
button, a, summary { -webkit-tap-highlight-color: transparent; }
button { font: inherit; cursor: pointer; }
button:focus-visible, a:focus-visible, summary:focus-visible { outline: 3px solid #075bb8; outline-offset: 4px; }
button:disabled { cursor: default; }
[hidden] { display: none !important; }
.shell { max-width: 430px; margin: 0 auto; padding: 24px 20px 20px; }
.page-header { display: flex; justify-content: space-between; align-items: center; margin-bottom: 28px; }
.wordmark { text-decoration: none; color: inherit; font-weight: 900; font-size: 26px; letter-spacing: -2px; }
.wordmark span { color: #267d7d; padding-left: 5px; }
.edition { font-size: 11px; color: #6a7778; }
.eyebrow { font-size: 11px; color: #617373; margin: 0 0 9px; }
h1 { font-size: 25px; line-height: 1.25; letter-spacing: -1.3px; margin: 0 0 12px; }
.intro > p:last-child { font-size: 12px; line-height: 1.8; margin: 0 0 20px; color: #536567; }
.game { border: 1px solid #c8d1ca; background: #fffdf6; border-radius: 22px; box-shadow: 0 12px 30px #20353d0b; overflow: hidden; }
.game-bar { display: flex; justify-content: space-between; align-items: center; gap: 12px; padding-inline: 17px; min-height: 44px; font-size: 10px; font-weight: 700; border-bottom: 1px solid #dfe4d9; }
#counter { font-variant-numeric: tabular-nums; }
#scene-restart { min-height: 44px; padding: 8px 0 8px 10px; border: 0; background: none; color: #315b50; font-size: 10px; }
.stage { position: relative; aspect-ratio: 360 / 550; isolation: isolate; overflow: hidden; background: #edf1df; touch-action: pan-y; container-type: inline-size; }
.quiet-scene { position: absolute; inset: 0; overflow: hidden; background: linear-gradient(#d8ece7, #eef0d9); }
.sun { position: absolute; top: 12%; left: 17%; width: 19%; aspect-ratio: 1; border-radius: 100%; background: #fff5cc; }
.hill { position: absolute; width: 150%; height: 52%; border-radius: 50% 50% 0 0; bottom: -10%; left: -33%; background: #82a58c; transform: rotate(16deg); }
.hill-front { left: 5%; bottom: -22%; background: #476f62; transform: rotate(-20deg); }
.quiet-copy { position: absolute; left: 0; right: 0; top: 35%; text-align: center; line-height: 1.8; }
.quiet-copy span { display: block; font-size: 12px; }
.quiet-copy strong { font-size: 6cqw; font-weight: 700; letter-spacing: -1px; }
.quiet-copy small { display: block; font-size: 11px; color: #61716b; margin-top: 8px; }
.balloon { position: absolute; --air: 1; --removed: 0; z-index: 2; transition: opacity .25s; pointer-events: none; }
.balloon-body { height: 100%; padding: 4cqw 4.5cqw; background: var(--balloon); border: 2px solid #20353d; border-radius: 30px 38px 32px 32px; box-shadow: 3px 6px 0 #20353d20; transform: scale(calc(.35 + var(--air) * .65)); transform-origin: var(--valve-origin) 100%; position: relative; pointer-events: auto; cursor: grab; transition: transform .08s linear; }
.balloon-body::before { content: ''; position: absolute; top: 10px; left: 20px; width: 32%; height: 5px; background: #ffffff70; border-radius: 8px; }
