import test from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { runInNewContext } from 'node:vm';

// Executes real application handlers, but does not render, hit-test, or emulate
// native browser capture delivery. Those remain explicit manual checks.
function createApp() {
  const read = name => readFileSync(new URL(`../${name}`, import.meta.url), 'utf8');
  let document;
  const deferred = [];
  class Element {
    constructor() {
      this.listeners = new Map(); this.children = []; this.attributes = new Map();
      this.classes = new Set(); this.hidden = false; this.disabled = false; this.captures = new Set();
      this.releaseCalls = 0;
      this.style = { setProperty: (name, value) => { this.style[name] = String(value); } };
      this.classList = {
        add: name => this.classes.add(name), remove: name => this.classes.delete(name), contains: name => this.classes.has(name),
        toggle: (name, force) => { const add = force ?? !this.classes.has(name); if (add) this.classes.add(name); else this.classes.delete(name); return add; },
      };
    }
    set className(value) { this.classes = new Set(value.split(/\s+/).filter(Boolean)); }
    set innerHTML(value) {
      this.parts = {};
      for (const name of ['balloon-body', 'knot', 'air-lines', 'handle', 'handle-material']) {
        const child = new Element(); child.className = name; this.parts[`.${name}`] = child;
      }
      this.append(this.parts['.balloon-body'], this.parts['.knot'], this.parts['.air-lines'], this.parts['.handle']);
      this.parts['.handle'].append(this.parts['.handle-material']);
      assert.match(value, /class="handle"/);
    }
    querySelector(selector) { return this.parts?.[selector] ?? null; }
    setAttribute(name, value) { this.attributes.set(name, value); }
    append(...children) { children.forEach(child => { child.parent = this; this.children.push(child); }); }
    replaceChildren(...children) { this.children.forEach(child => { child.parent = null; }); this.children = []; this.append(...children); }
    contains(child) { return child === this || this.children.some(node => node.contains(child)); }
    closest(selector) { return selector === '.game' && this.classes.has('game') ? this : this.parent?.closest(selector); }
    focus() { if (document.activeElement !== this) { document.activeElement = this; this.emit('focus'); } }
    addEventListener(type, handler) { if (!this.listeners.has(type)) this.listeners.set(type, []); this.listeners.get(type).push(handler); }
    emit(type, properties = {}) {
      const event = { type, target: this, detail: 0, defaultPrevented: false, preventDefault() { this.defaultPrevented = true; }, ...properties };
      for (const handler of this.listeners.get(type) ?? []) handler(event);
      return event;
    }
    getBoundingClientRect() { return { left: 20, top: 80, width: 360, height: 550 }; }
    setPointerCapture(id) { if (this.captureFailure) { const error = new Error('Inactive pointer'); error.name = 'NotFoundError'; throw error; } this.captures.add(id); }
    hasPointerCapture(id) { return this.captures.has(id); }
    releasePointerCapture(id) {
      this.releaseCalls++;
      if (!this.captures.delete(id)) return;
      const lost = () => this.emit('lostpointercapture', { pointerId: id });
      if (this.deferLost) deferred.push(lost); else lost();
    }
  }
  const nodes = new Map();
  for (const match of read('index.html').matchAll(/<[^>]+\bid="([^"]+)"[^>]*>/g)) {
    const node = new Element(); node.hidden = /\shidden(?:\s|>)/.test(match[0]);
    node.className = /\bclass="([^"]*)"/.exec(match[0])?.[1] ?? ''; nodes.set(match[1], node);
  }
  const get = id => { assert.ok(nodes.has(id), `index.html must contain #${id}`); return nodes.get(id); };
  document = new Element(); document.getElementById = get; document.createElement = () => new Element(); document.hidden = false;
  get('game').append(get('stage'));
  get('stage').append(get('pieces'), get('finish'));
  get('finish').append(get('finish-title'), get('restart'));
  for (const key of ['ArrowLeft', 'ArrowRight', 'ArrowUp', 'ArrowDown']) get('direction-controls').append(get(key));
  const window = new Element(); window.innerWidth = 900; window.innerHeight = 900;
  const context = { document, window };
  runInNewContext(`${read('src/scenes.js')}\n${read('src/puzzle.js')}\n${read('src/app.js')}`, context);
  const core = context.PuffPuzzle;
  const scene = () => core.getScene(get('stage').attributes.get('data-scene'));
  const piece = index => get('pieces').children[index];
  const handle = index => piece(index).querySelector('.handle');
  const fraction = index => Number(piece(index).style['--removed']);
  const point = (index, progress = fraction(index)) => {
    const item = scene().items[index];
    return { x: item.target.x + item.vector.x * progress, y: item.target.y + item.vector.y * progress };
  };
  const pointer = (type, index = 0, where = point(index), extra = {}, node = handle(index)) => node.emit(type, { pointerId: 7, isPrimary: true, button: 0, buttons: 1, clientX: where.x + 20, clientY: where.y + 80, ...extra });
  const half = (index = 0) => { pointer('pointerdown', index); pointer('pointermove', index, point(index, .5)); assert.equal(fraction(index), .5); };
  const noCapture = () => { for (let i = 0; i < scene().items.length; i++) { assert.equal(handle(i).hasPointerCapture(7), false); assert.equal(handle(i).classList.contains('dragging'), false); } };
  function clearRound() {
    for (let index = scene().items.length - 1; index >= 0; index--) {
      pointer('pointerdown', index);
      pointer('pointermove', index, point(index, 1));
      pointer('pointerup', index, point(index, 1), { buttons: 0 });
      handle(index).emit('click', { detail: 1 });
    }
    assert.equal(get('finish').hidden, false);
    assert.equal(document.activeElement, get('finish-title'));
    noCapture();
  }
  return { core, get, document, window, scene, piece, handle, fraction, point, pointer, half, noCapture, clearRound, flushLost: () => deferred.splice(0).forEach(fn => fn()) };
}

for (const sceneId of ['balloons', 'coupons']) {
  for (const reason of ['pointercancel', 'lostpointercapture', 'blur', 'hidden', 'pagehide', 'outside', 'released-outside', 'document-exit']) {
    test(`${sceneId}/${reason}: preserve partial work and resume by grabbing its moved end`, () => {
      const app = createApp(); app.get(`scene-${sceneId}`).emit('click'); app.half();
      if (reason === 'pointercancel') app.pointer('pointercancel');
      if (reason === 'lostpointercapture') app.handle(0).releasePointerCapture(7);
      if (reason === 'blur') app.window.emit('blur');
      if (reason === 'hidden') { app.document.hidden = true; app.document.emit('visibilitychange'); }
      if (reason === 'pagehide') app.window.emit('pagehide');
      if (reason === 'outside') app.pointer('pointermove', 0, app.point(0), { clientX: -1 });
      if (reason === 'released-outside') app.pointer('pointermove', 0, app.point(0), { buttons: 0 });
      if (reason === 'document-exit') app.document.emit('pointerout', { pointerId: 7, relatedTarget: null });
      app.noCapture();
      app.pointer('pointermove', 0, app.point(0, 1)); assert.equal(app.fraction(0), .5);
      app.document.hidden = false;
      app.pointer('pointerdown'); app.pointer('pointermove', 0, app.point(0, 1));
      assert.equal(app.fraction(0), 1); app.noCapture();
    });
  }
  test(`${sceneId}: complete twice with fresh controls, focus, and zero leaked progress`, () => {
    const app = createApp(); app.get(`scene-${sceneId}`).emit('click'); app.clearRound();
    const oldHandle = app.handle(0);
    app.get('restart').emit('click');
    assert.equal(app.get('finish').hidden, true);
    assert.equal(app.get('stage').attributes.get('data-scene'), sceneId);
    assert.equal(app.fraction(0), 0); assert.equal(app.handle(0).disabled, false);
    oldHandle.emit('click'); assert.equal(app.fraction(0), 0);
    app.clearRound();
  });
}
test('body presses visibly probe and a short direct drag immediately changes object shape', () => {
  const app = createApp();
  app.piece(0).querySelector('.balloon-body').emit('pointerdown');
  assert.equal(app.piece(0).classList.contains('probe'), true); assert.equal(app.fraction(0), 0);
  app.pointer('pointerdown'); app.pointer('pointermove', 0, app.point(0, .1));
  assert.ok(Math.abs(app.fraction(0) - .1) < 1e-9);
  assert.equal(app.piece(0).classList.contains('probe'), false);
});
test('wrong motion gives tension, and opposite-facing knots have visibly opposite travel', () => {
  const app = createApp(); app.pointer('pointerdown');
  app.pointer('pointermove', 0, { x: 200, y: 184 });
  assert.equal(app.piece(0).classList.contains('strained'), true); assert.equal(app.fraction(0), 0);
  app.pointer('pointercancel'); app.pointer('pointerdown', 1);
  app.pointer('pointermove', 1, app.point(1, .5)); assert.ok(Math.abs(app.fraction(1) - .5) < 1e-9);
});
test('click alone never clears, keyboard focus selects, and both keyboard directions matter', () => {
  const app = createApp(); app.handle(1).focus();
  app.handle(1).emit('click'); assert.equal(app.fraction(1), 0);
  app.document.emit('keydown', { key: 'ArrowRight' }); assert.equal(app.fraction(1), 0);
  app.document.emit('keydown', { key: 'ArrowLeft' }); assert.ok(app.fraction(1) > 0);
  app.document.emit('keydown', { key: 'Escape' });
  assert.equal(app.get('ArrowLeft').disabled, true);
});
test('tap then optional directional buttons works for a partial object as well as a fresh one', () => {
  const app = createApp(); app.half(); app.pointer('pointerup');
  app.pointer('pointerdown'); app.pointer('pointerup');
  app.get('ArrowRight').emit('click');
  assert.ok(app.fraction(0) > .5);
});
test('quick drag can complete on pointerup even when the browser omits intermediate moves', () => {
  const app = createApp(); app.pointer('pointerdown');
  app.pointer('pointerup', 0, app.point(0, 1), { buttons: 0 });
  assert.equal(app.fraction(0), 1); app.noCapture();
});
test('capture failure ends cleanly, and secondary pointer cannot take ownership', () => {
  const app = createApp(); app.handle(0).captureFailure = true;
  assert.doesNotThrow(() => app.pointer('pointerdown')); app.noCapture();
  app.handle(0).captureFailure = false; app.pointer('pointerdown');
  app.pointer('pointerdown', 1, app.point(1), { pointerId: 8, isPrimary: false });
  app.pointer('pointermove', 0, app.point(0, 1), { pointerId: 8 });
  assert.equal(app.fraction(0), 0); assert.equal(app.handle(0).hasPointerCapture(7), true);
});
test('reset and scene switch ignore detached callbacks and deferred old capture loss', () => {
  const app = createApp(); const oldHandle = app.handle(0), oldBody = app.piece(0).querySelector('.balloon-body');
  oldHandle.deferLost = true; app.half(); app.get('scene-coupons').emit('click');
  app.pointer('pointerdown'); app.flushLost();
  oldHandle.emit('click'); oldBody.emit('pointerdown');
  assert.equal(app.handle(0).hasPointerCapture(7), true); assert.equal(app.fraction(0), 0);
  app.pointer('pointermove', 0, app.point(0, .5));
  app.get('scene-restart').emit('click'); app.noCapture(); assert.equal(app.fraction(0), 0);
  app.clearRound();
});
test('coupon first corner exists before input and its clipping changes during drag', () => {
  const app = createApp(); app.get('scene-coupons').emit('click');
  const initial = app.piece(0).querySelector('.balloon-body').style.clipPath;
  assert.match(initial, /84%/); app.half();
  assert.notEqual(app.piece(0).querySelector('.balloon-body').style.clipPath, initial);
  assert.match(app.handle(0).attributes.get('aria-label'), /50%/);
});
test('repeated scene changes do not accumulate shared listeners', () => {
  const app = createApp();
  const controls = [app.document, app.window, app.get('ArrowLeft'), app.get('scene-balloons'), app.get('scene-coupons'), app.get('restart')];
  const counts = () => controls.map(control => [...control.listeners].map(([name, handlers]) => [name, handlers.length]));
  const before = counts();
  for (let i = 0; i < 5; i++) { app.get('scene-coupons').emit('click'); app.get('scene-balloons').emit('click'); }
  assert.deepEqual(counts(), before);
});

