import test from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { createHash } from 'node:crypto';

const read = name => readFileSync(new URL(`../${name}`, import.meta.url), 'utf8');
test('original BRIEF.md bytes are preserved', () => {
  const bytes = readFileSync(new URL('../BRIEF.md', import.meta.url));
  assert.equal(createHash('sha256').update(bytes).digest('hex'), 'ee15d9dd52fe4a9752ab2bd70ba9bf205d03b5790b67787b668f2753c11959ab');
});
test('entrypoint loads existing local classic scripts in dependency order', () => {
  const html = read('index.html');
  const sources = [...html.matchAll(/<script src="([^"]+)" defer><\/script>/g)].map(match => match[1]);
  assert.deepEqual(sources, ['src/scenes.js', 'src/puzzle.js', 'src/app.js']);
  sources.forEach(source => assert.ok(read(source).length));
  const stylesheets = [...html.matchAll(/<link rel="stylesheet" href="([^"]+)">/g)].map(match => match[1]);
  assert.deepEqual(stylesheets, ['styles.css', 'layout.css']);
  stylesheets.forEach(source => assert.ok(read(source).length));
  assert.ok(!html.includes('type="module"'), 'direct file opening must not require a module server');
});
test('prototype has no declared external resources or networking calls', () => {
  const source = ['index.html', 'styles.css', 'layout.css', 'src/scenes.js', 'src/puzzle.js', 'src/app.js'].map(read).join('\n');
  assert.doesNotMatch(source, /(?:src|href)=["'](?:https?:)?\/\//i);
  assert.doesNotMatch(source, /\b(?:fetch|XMLHttpRequest|WebSocket|sendBeacon)\s*\(/);
  assert.doesNotMatch(source, /@import\s|url\(\s*["']?https?:/);
});

