import test from 'node:test';
import assert from 'node:assert/strict';
import '../src/scenes.js';
import '../src/puzzle.js';
const game = globalThis.PuffPuzzle;
const at = (point, vector, fraction) => ({ x: point.x + vector.x * fraction, y: point.y + vector.y * fraction });

for (const scene of Object.values(game.SCENES)) {
  for (const item of scene.items) {
    test(`${item.id}: direct contact and taps do not solve; motion gives continuous feedback`, () => {
      let state = game.fresh(scene.id);
      state = game.select(state, item.id);
      assert.equal(state.pieces.find(p => p.id === item.id).progress, 0);
      state = game.begin(state, item.id, item.target, 7);
      assert.equal(state.pieces.find(p => p.id === item.id).progress, 0);
      state = game.move(state, at(item.target, item.vector, .01), 7);
      assert.ok(Math.abs(state.pieces.find(p => p.id === item.id).progress - .01) < 1e-9);
      state = game.move(state, at(item.target, item.vector, .5), 7);
      assert.equal(state.pieces.find(p => p.id === item.id).progress, .5);
      assert.deepEqual(game.position(state, item.id), at(item.target, item.vector, .5));
      state = game.move(state, at(item.target, item.vector, 1), 7);
      assert.equal(state.pieces.find(p => p.id === item.id).progress, 1);
      assert.equal(state.drag, null);
    });
    test(`${item.id}: wrong and perpendicular motion resist without progress`, () => {
      let state = game.begin(game.fresh(scene.id), item.id, item.target, 7);
      state = game.move(state, at(item.target, item.vector, -.5), 7);
      assert.equal(state.pieces.find(p => p.id === item.id).progress, 0);
      assert.equal(state.feedback.kind, 'strain');
      assert.ok(Math.abs(Math.hypot(state.feedback.x, state.feedback.y) - 6) < 1e-9);
      state = game.move(state, at(item.target, { x: -item.vector.y, y: item.vector.x }, .5), 7);
      assert.equal(state.pieces.find(p => p.id === item.id).progress, 0);
    });
    test(`${item.id}: released partial work stays at the moved end and resumes without jumping`, () => {
      let state = game.begin(game.fresh(scene.id), item.id, item.target, 7);
      state = game.move(state, at(item.target, item.vector, .5), 7);
      state = game.end(state, 7);
      const held = game.position(state, item.id);
      const fingertip = { x: held.x + 8, y: held.y - 6 };
      state = game.begin(state, item.id, fingertip, 8);
      assert.deepEqual(game.position(state, item.id), held);
      state = game.move(state, at(fingertip, item.vector, .5), 8);
      assert.equal(state.pieces.find(p => p.id === item.id).progress, 1);
    });
  }
  test(`${scene.id}: arbitrary order completes, disabled objects stay cleared, and fresh restarts are isolated`, () => {
    let state = game.fresh(scene.id);
    for (const item of [...scene.items].reverse()) {
      state = game.begin(state, item.id, item.target, 7);
      state = game.move(state, at(item.target, item.vector, 1), 7);
      assert.equal(game.select(state, item.id), state);
      assert.equal(game.begin(state, item.id, item.target, 7), state);
    }
    assert.equal(state.completed, true);
    const fresh = game.fresh(scene.id);
    assert.ok(fresh.pieces.every(piece => piece.progress === 0));
    assert.equal(fresh.sceneId, scene.id);
    assert.ok(state.pieces.every(piece => piece.progress === 1));
  });
}
test('secondary pointers, malformed input, and unknown pieces cannot hijack a drag', () => {
  const state = game.begin(game.fresh(), 'flash', { x: 229, y: 184 }, 7);
  assert.equal(game.move(state, { x: 400, y: 184 }, 8), state);
  assert.equal(game.end(state, 8), state);
  assert.equal(game.begin(state, 'bonus', { x: 20, y: 40 }, 8), state);
  assert.equal(game.move(state, { x: NaN, y: 184 }, 7), state);
  const fresh = game.fresh();
  assert.equal(game.begin(fresh, 'missing', { x: 0, y: 0 }), fresh);
  assert.equal(game.begin(fresh, 'flash', { x: NaN, y: 0 }), fresh);
  assert.equal(game.nudge(fresh, 'ArrowRight'), fresh);
});
test('body exploration produces a physical clue without solving or selecting', () => {
  for (const scene of Object.values(game.SCENES)) {
    const state = game.probe(game.fresh(scene.id), scene.items[0].id);
    assert.equal(state.feedback.kind, 'probe');
    assert.equal(state.selected, null);
    assert.equal(state.pieces[0].progress, 0);
  }
});
test('left-facing knot and right-facing knot require different keys', () => {
  let right = game.select(game.fresh(), 'flash');
  let left = game.select(game.fresh(), 'bonus');
  right = game.nudge(right, 'ArrowLeft');
  left = game.nudge(left, 'ArrowRight');
  assert.equal(right.pieces[0].progress, 0);
  assert.equal(left.pieces[1].progress, 0);
  right = game.nudge(right, 'ArrowRight');
  left = game.nudge(left, 'ArrowLeft');
  assert.ok(right.pieces[0].progress > 0);
  assert.ok(left.pieces[1].progress > 0);
});
test('coupon keys move the same diagonal fold; reverse keys cannot peel', () => {
  let state = game.select(game.fresh('coupons'), 'coupon-million');
  state = game.nudge(state, 'ArrowRight');
  state = game.nudge(state, 'ArrowUp');
  assert.equal(state.pieces[0].progress, 0);
  state = game.nudge(state, 'ArrowLeft');
  const progress = state.pieces[0].progress;
  state = game.nudge(state, 'ArrowDown');
  assert.ok(state.pieces[0].progress > progress);
  assert.ok(game.position(state, 'coupon-million').x < 316);
  assert.ok(game.position(state, 'coupon-million').y > 62);
});
test('floating point noise completes, but a one-pixel-short pull does not', () => {
  let state = game.begin(game.fresh(), 'flash', { x: 229, y: 184 }, 7);
  state = game.move(state, { x: 272, y: 184 }, 7);
  assert.ok(state.pieces[0].progress < 1);
  state = game.move(state, { x: 273 - 1e-10, y: 184 }, 7);
  assert.equal(state.pieces[0].progress, 1);
});
test('stationary pointer samples after progress do not invent resistance', () => {
  let state = game.begin(game.fresh(), 'flash', { x: 229, y: 184 }, 7);
  state = game.move(state, { x: 251, y: 184 }, 7);
  state = game.move(state, { x: 251, y: 184 }, 7);
  assert.equal(state.feedback, null);
  assert.equal(state.event, 'progress');
  assert.equal(state.pieces[0].progress, .5);
});

