import test from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import '../src/scenes.js';
import '../src/puzzle.js';
const game = globalThis.PuffPuzzle;
const read = name => readFileSync(new URL(`../${name}`, import.meta.url), 'utf8');

test('two ad themes, counts, unknown scene fallback, and immutable configuration remain', () => {
  assert.equal(game.fresh().sceneId, 'balloons');
  assert.equal(game.fresh().pieces.length, 3);
  assert.equal(game.fresh('coupons').pieces.length, 2);
  for (const name of ['missing', '__proto__', 'constructor']) assert.equal(game.fresh(name).sceneId, 'balloons');
  assert.ok(Object.isFrozen(game.SCENES.coupons.items[0].vector));
});
test('all direct ends and their complete travel stay in the board at minimum width', () => {
  const logicalRadius = 24 * game.WIDTH / 260;
  for (const scene of Object.values(game.SCENES)) {
    for (const item of scene.items) {
      for (const fraction of [0, .5, 1]) {
        const point = { x: item.target.x + item.vector.x * fraction, y: item.target.y + item.vector.y * fraction };
        // Outer hit-box edges may crop slightly, but the 18px material remains reachable.
        assert.ok(point.x >= 20 && point.x <= game.WIDTH - 20);
        assert.ok(point.y >= logicalRadius && point.y <= game.HEIGHT - logicalRadius);
      }
    }
  }
});
test('coupon remainder reveals its initial corner and collapses to zero area at completion', () => {
  assert.match(game.paperClip(0), /84% 0, 100% 16%/);
  assert.notEqual(game.paperClip(0), game.paperClip(.5));
  assert.equal(game.paperClip(1), 'polygon(0 100%, 0% 100%, 0 100%)');
});
test('opening UI has object cues, no detached tool, step guide, or prescribed solution arrow', () => {
  const html = read('index.html');
  assert.doesNotMatch(html, /id="(?:tool|pull|pull-guide|scene-action)"/);
  assert.doesNotMatch(html, /집게|네 번|끼우고/);
  const app = read('src/app.js'), css = read('styles.css');
  assert.match(app, /class="knot"/);
  assert.match(css, /\.coupon \.handle-material/);
  assert.match(css, /\.probe \.balloon-body/);
  assert.match(css, /prefers-reduced-motion/);
  assert.match(css, /\.handle \{[^}]*width: 48px; height: 48px/s);
});
